from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1];W=R/'work'
b=copy.deepcopy(json.loads((R/'source/v69_rulebook.json').read_text()))
b.update(version='7.0',subtitle='双行排程与世代竞逐')
D={x['title'].split()[0]:x for s in b['sections'] for x in s['blocks']}
def set_(key,title,body,aside):
 D[key].update(title=key+' '+title,body=body,asideKind='例子 / 关联规则',aside=aside)
set_('1.1','一组配置是一批现货','普通产品位代表一批已经组装付款的手机。制造行动按强度可以依次组装1、2或3批；每批分别检查、付款和占用一个产品位。\n同一批只投一个零售市场、一张合同或留库。未售原样跨场，可在以后自己的行动阶段取消；不设旧机年龄、自动降分或自动退市。\n**发布扩产是例外：原产品初步获单后，每公司每场可追加一批同配置，另付成本、不占新产品位，且两批都必须当场获单。** 扩产见§13。','强度3制造最多组装三批，并非一张定制卡复制三次。每张定制实体仍只装一批；扩产才允许同组复用。')
set_('1.2','现金付成本，收入与科技相向走','现金用于入库、制造、研发、授权与经营，不是收入轨。收入是成交等商业成果，科技是本人研发与验证成果。\n**收入0—130、科技0—46，两种标记沿同一版图反向前进。科技0→8每步对齐2格收入，8→46每步对齐3格收入。** 直接按科技刻度移动，不在游玩时换算倍数。\n任意玩家自己的两个标记相遇或越过，即进入终局检查；先完成当前回合全部结算，再让每人各行动一次，随后最终发布。最终比较相遇线两侧的净距离，详见§15。\n授权款只是现金转账，不自动增加任何人的收入或科技。','科技22标记对齐收入72。收入50时还差22格；收入72时相遇。不是收入或科技各到一个独立数值就结束。')
set_('1.3','玩家用真实成果决定什么时候发布','没有固定轮数、销售季或每代固定发布次数。发布轨终点为2人8、3人12、4人16。\n制造和科研成果可以当场选择预告；已有至少两批合法现货的玩家也可用运营行动付费宣发。具体强度和额度在六张行动牌与§3写明。\n轨到终点后，完成该次行动及阵列整理，立即共同发布，没有额外响应回合。空桌的普通推进最多到终点前1；最终发布可为空。','只有拿钱、拿牌或签空合同，不会让发布轨前进。两次实际发布之间称为准备期，合同与每期能力跟随实际发布。')
set_('2.1','一个主牌市场，两个功能牌源','| 区域 | 组成与用法 |\n| --- | --- |\n| 主牌 | 稳定80、定制64、研发41、合同30、设施18、方案24，共257张，五代开局全混；公开8张。 |\n| 参考机 | 30张，五代各6张；每场锁定后从本场参考代完整6张现抽1张。 |\n| 需求 | 12张，准备期提前公开1张，不入手牌。 |\n| 初始件 | 16张，四家公司每人芯片、屏幕、影像、机身各1张，另发。 |\n全套315种、315张内容牌。另有每人六张行动牌与功能标记，**均不混入主牌**。不按厂或世代另开商店。','每代4张稳定芯片＋6张含芯片定制，合计50个唯一芯片名。主牌卡量与6.9相同。')
set_('2.2','开局摆公共区与公司区','随机先手，顺时针行动。洗主牌、翻8张；需求首场用N01，其余11张洗好；供应与参考世代置I，发布置0。\n每人120现金、收入0、科技0；4产品位、2在研槽、1合同槽、3设施空间。抽8张主牌留5，余牌进主弃牌；回合末手牌上限8。\nA/B/C/D分别使用M01/M02/M03/M04的四张初始实体，免费装入稳定库；初始中立不建立五厂关系，不赠送现货。\n六行动固定开局：上行从1到3为【调研、供应、制造】，下行为【合作、研发、运营】。所有玩家相同，两行没有职业限制。\n五厂关系普通，核心为空，公共技术区为空。扩产状态放可用。','行动强度来自所处列，不是牌上另有等级。五厂颜色不是玩家颜色；A可与任何厂合作。')
set_('2.3','公开信息与秘密信息','公开现金、收入与科技、六行动位置、稳定库、关系、在研模式与进度、科研成果署名、合同、产品位是否占用、需求和本场参考世代。\n手牌和首次发布前的产品配置、售价、去向保持秘密。技术使用指派背面仅显示公司，发布时翻开产品号；已揭晓未售产品与指派继续公开。\n每人16张稳定代替卡、12枚技术指派（四产品各3）、35枚署名圆片、5关系片、1核心片、3联合在研片，以及每项研究1枚进度标记。没有工作点、代龄或保留券。\n扩产选择与付款公开。阵列中的每次交换两个1也公开，不重新洗行动牌。','圆形作者片永久保留；长方使用片随产品结束收回。研究只记0—8进度；阵列直接用6张牌记录，不加准备度计数器。')
# Replace chapter 3 with concise complete operating manual.
s=b['sections'][2];s['title']='六行动双行排程';s['intro']='六张牌一直可选。一次回合只选一张，按当前强度执行，然后整理本行并决定是否交换两行的1。'
s['blocks']=[]
def block(key,title,body,aside):
 x={'title':key+' '+title,'body':body,'asideKind':'例子 / 摆法','aside':aside};s['blocks'].append(x)
block('3.1','先做行动，再整理位置','选一张行动，以使用前所在列的1/2/3为本次强度。完成其一整行效果后，拿出该牌；本行其他两张保持原先相对顺序，放到2、3，再将用牌放回本行1。\n**随后可交换上、下两行的强度1各一张，也可不换。** 每回合只选择一次，不可先换再选行动。另一行不自动升强度。\n发布不重置阵列，额外取牌、安装和发布扩产不算第二个行动，也不整理第二次。','下行D/E/F，使用E后成为E/D/F。若再与上行1的A交换，下行成为A/D/F，E移到上行1。使用1时本行顺序不变，仍可选择跨行交换。')
block('3.2','六张牌的强度表','| 行动 | 强度1／2／3的主要效果 |\n| --- | --- |\n| 调研 | 取至多2／3／4张，牌市和盲抽可混选。 |\n| 供应 | 安装1／1／至多2张不同类别稳定件；强度2或3完成安装后可盲抽1张。 |\n| 研发 | 给1个项目推进1／2／4格，可立项，不能转移剩余进度。 |\n| 制造 | 逐批组装至多1／2／3批，分别付款和占位。 |\n| 合作 | 处理1项企业事项；强度2或3成功后可盲抽1／2张。 |\n| 运营 | 拿6／12／18现金；或符合条件时付3现金宣发，推进1／1／2格。 |\n所有强度都保留基本功能。现金仍照卡支付，强度不提高手机质量。','连续用制造可以一直以1强度造一批；要恢复较高强度，需要使用同一行其他牌，或把它换到另一条循环。没有任何牌被禁用。')
block('3.3','调研、供应与合作不互相冒充','调研只取得牌，不能顺便安装、签约或研究。选牌全部结束后一次补空位。\n供应从手牌依次安装；同一次强度3供应至多两种不同部件，每张单独付款。强度2/3必须真的装好至少1张，才可附抽1张；附抽在全部安装结束后，不能继续装刚抽到的牌。\n合作在签1合同、建1设施、建立/切换核心中选一项，付钱并查前置；同次不能做第二项。强度2/3的附抽在事项完成后进行，不立刻打出。','不能空选供应领取附抽；不能空选合作拿牌。强度高也不免入库费、建设费和核心费。关系按每项业务完成后更新，后续安装可享新关系。')
block('3.4','研发只推进一个项目','一次研发选择手牌中的一个新项目立项，或选择一个已有项目推进/复核。本次强度给出的1/2/4格已经包含立项，不额外再送1格。\n本次最多处理且完成一个项目。进度到所选模式工期即停，剩余额度不转给别的项目。缺证明停在待验证，以后再选研发复核。实验室依法加速，也只作用于该项目。\n也可放弃全部进度，改为独立验证：付12现金、出示基础竞争力至少12且至少2特征的真实现货，每公司每当前世代一次得1科技。任何强度可选，详见§9。','联合工期3，用强度3立项并给4格，只到3并检查证据；不会又免费立第二项。自主工期7，可用4＋2＋1完成。')
block('3.5','成果预告：行动完成后才决定','强度2制造：本次真正组装且在行动结束时仍存在至少1批，可推进1格。强度3制造：按本次实际保留的新批数推进，最多2格。强度1不预告。\n强度2/3研发行动完成所选本人项目，可推进1格；独立验证、只立项未完成、奖励中完成研究、签约、取牌、入库和取消都不产生预告。\n可推较少或放弃，不能留到以后。制造附加额度与实验室不会改变本次原强度或预告上限；扩产不预告。','强度3做了3批可推0、1或2格；只做1批最多推1。强度1经U02做了2批，仍不能预告。取消本次新货不能同时保留它的预告。')
block('3.6','有货才能付费宣发','运营的现金与宣发二选一。选择宣发时，行动开始前本人须有至少2批合法、已经付款且尚未结束占用的现货；付3现金，按强度1/2/3可推进1/1/2格。宣发不再拿运营现金，也不补产。\n全桌没有合法现货时，普通推进最多到终点前1格；不能凭科研反复空发布。以后有货也不会自动补那一格，仍须有人取得合法推进机会。\n进度到终点后不再取消产品或换配置；完成阵列整理立即发布。最终发布按终局规则无条件举行。','四个产品位全满仍可运营宣发，不必取消重造。只囤一批、空运营或无产品科研不能刷空发布。有人有货后主动抢开是正常竞争。')
block('3.7','一个回合如何结束','本人回合开始，恢复本人回合限次；可以做牌面明确允许的行动前事项。免费取消可在选行动前、或制造的批次之间进行，不会取得第二次行动。\n选择并完成一次六行动及其合法附加效果 → 决定成果预告 → 整理本行、可交换两个1 → 手牌弃至上限 → 发布到顶则完整发布 → 开放本回合达到的新世代 → 检查相遇终局 → 下一人。\n牌面额外拿牌、安装、研究进度都不改变阵列次数。新设施不回溯本次行动开始前的触发；共同发布中只执行明文允许的扩产与奖励窗口。','若一次行动既科技到门槛又推满发布，先按当前世代发布，再开放新代、标定下一场参考代。不要中途换参考机或用新代配件补货。')
# Remaining chapters preserve 6.9 system except explicitly approved changes.
set_('4.1','先选完，再补一次','调研行动强度1/2/3取得至多2/3/4张主牌；每张选当前牌市或主堆顶盲抽，可混选。所有牌先入手并占手牌，不另收取得现金。\n选择期间空位留空，不左移、不补新牌供本次再挑；选完后统一补空位。附加连续取牌奖励也按整个奖励结束补一次。\n主堆空时仅洗主弃牌；库内牌、现货、在研、已完成、合同归档和移出区不能混回。无牌就只取实际有的。','同次选牌不能拿走2号、补出一张，再把新2号拿走。未来卡照样会抽到，但不能提前用于产品。')
set_('4.2','领先科技开放新代，不另设产业轨','全桌任意一人科技第一次达到4／9／15／22，分别开放II／III／IV／V代；在该回合全部行动与可能的发布结束后生效。多门槛同回合到达，直接开放最高相应世代。\n所有五代已在主牌堆中；换代只改变可用权限，不加牌、不刷新商店、不计发布场数、不统计公共产业贡献。配件与Q的世代不得高于当前供应代；研发、合同、设施按自身前置使用。\n本准备期参考世代固定，中途供应换代不改变它。普通发布整理完并开放新代后，标定下一场参考代；具体参考机仍等下次锁定后抽。','每代约两场只是实测目标。领先科技可以提前换代，不要求全桌都贡献，也不等固定第二场。内容五代仍对应2017—2026的两年窗口。')
set_('5.3','核心合作开放联合研发','已经是目标厂伙伴，可用合作行动选择建立/切换核心并付12现金；全公司同时最多一家，各公司可选同厂。不占合同槽、不直接得分、不提供五套固定被动技能。\n首次核心可并入首次联合立项：尚未选过核心时，可在研发行动中同付12核心费和联合费，确立核心并给项目本次完整1/2/4进度。先确认全部伙伴、前置、部件、槽位和现金再执行。\n以后切换须合作行动并付12；任何未结束联合项目存在时不能切换，须先完成或放弃。旧公开成果与作者署名不撤回，不迁厂。','强度3首次联合T01：付12＋9，项目至多获得4格、到工期2即停。首次合并不等于先免费合作再额外研发一次。')
set_('5.4','所有具体价格都印在相应卡上','稳定件按当时关系选卡面普通入库价或本厂伙伴价，核心同伙伴；其他明确减免从所选价继续扣到0，不返还多余折扣。价格差逐卡不同。\n研发卡直接印自主/联合各自现金与工期、完成科技、每批授权费和关联部件。两种模式不按固定倍数互推。\n六行动牌印各强度额度；个人版图印核心12现金、独立验证12现金和宣发3现金等共通数字。卡面不重复印“取得0”，初始另写开局免费。','卡印普通13/伙伴3，不能先按3付款再减一次10差额。授权现金给作者，制造现金给银行，两笔分别支付。')
set_('6.1','取得与入库是两件事','芯片、屏幕、影像、机身各一个稳定栏，初始也占栏，没有隐藏备用库。\n供应行动按强度从手牌安装稳定件，付普通/伙伴入库费，替换同类原卡。被换下的非初始卡进主弃牌，初始卡移出本局；不退原入库费。定制不能装进库。\n未来世代可以付费装入，却暂时不能用于组装或样机；有产品引用的栏位不能撤下、替换或挪动。奖励签装等例外也不突破锁定。','强度3可安装两类，但不是四栏全换。第一次安装建立伙伴后，第二项同厂安装可使用已生效的伙伴价，仍需不同类别。')
set_('7.1','按制造强度，逐批配齐付款','一次制造行动强度1/2/3，依次组装至多1/2/3批。每批选择空位，恰好配齐芯片、屏幕、影像和机身，来源为库内稳定代替卡或手中定制。整张定制必须同批全用、不拆不重叠。\n每批可加至多1张Q，并指派自有或已合法购买的联合技术。先查世代、供电、折叠、兼容、Q、技术位、同公司技术占用、伙伴与联合适配，再付制造款和全部授权款，放使用片。\n逐批完成后才能开始下一批；同张定制或部署技术不能重复占用。剩余额度可放弃。合法完成该批后建立其定制厂伙伴，新关系不能倒过来满足刚完成这批的授权。','一张稳定芯片可供三批；一张定制芯片只能装一批。组装不是免费，每批有自己的费用和产品位。')
set_('7.4','制造款与授权款分开结清','制造款给银行：四部件印刷制造费＋有效组装费＋Q方案费−明确总减免，最低6。通用组装费8，只减组装费先到0；多项定制各行相加。\n外部授权款逐项给署名作者，另加在制造款之外，不参与制造最低值或通用减免。开始每批前现金须足够两者总和；原作者自用不向自己付款。\n普通制造的第一批优惠按行动限一次，不因接着做第二批重置。扩产按发布开始的冻结配置及持续减免重算，不回忆历史付款，也不享受正常制造/首次/取消优惠。','强度3有三批机会，但U11只减第一批组装费；扩产另付制造与授权，不再支付入库费，不用本场销售款垫付。')
set_('7.6','规格有代际梯度，不是现实跑分','芯片规格是压缩的产品能力档位；负载不是瓦数，制造费不是现实报价。同系列代际以8 Gen 2＝12、8 Gen 3＝14、8 Elite＝17作锚点；第五代继续有增长空间。\n配件值直接读卡，不按世代再加分或自动折价。芯片与影像不印无意义的直板属性；屏幕、机身仍分直板与折叠。\n48售价通常须基础竞争力≥28，并满足芯片规格≥12或影像规格≥8至少一项；卡牌明确许可可替代。高价仍要符合需求预算。性能通常芯片≥6，影像通常影像≥6，保持入门市场可达性。\n每张卡的适配、样机、费用与专长都按自身文字；同一规格不表示两款真实芯片完全等速。','新一代同类芯片主要性能更强，旧平台仍可更便宜、适合既有供应商。强芯片不让研发、授权或扩产免费。最新两款的来源与未统一实测边界见芯片资料说明。')
set_('8.1','取消回件，不退投入','在自己正常行动阶段，选行动之前或制造批次之间，可免费取消尚未成交产品。制造／授权现金、已用行动与已领奖科研不退。\n定制与Q整张回手，代替卡和使用指派收回，产品位清空；稳定实体留库。其他产品仍引用就仍锁定。取消不复位回合、准备期、验证或扩产限次。\n发布开始或预告已把轨推至终点后不能取消、换价、换库、改配置。取消不是行动，不移动阵列。','刚造好又取消，不产生可保留的制造预告。额外组件只有回到手里的实际那张卡，不生成第二套。')
set_('8.2','改款就是取消后重新制造','基础规则没有免费修改已经付款现货的步骤。取消原批，再在制造行动额度内用调整后的配置重组，重新检查并付完整费用。\nT31/U14只奖励制造行动内取消后紧接同位的那一次组装；在选行动前取消、之后隔着其他事项，不能追溯其优惠。每次制造行动各最多一次。\n普通复制另一批占另一空位，定制与技术不得重复使用；只有发布扩产可在同组追加一批。','修正配置不是修改旧数值。未售等下场不重付；主动改款才取消再付款。')
set_('9.1','选一个项目与一种模式，投入整次进度','研发行动只选择一个新项目立项或一个在研项目推进。立项从手牌支付卡面所选模式费用，占在研槽；强度1/2/3给1/2/4进度，已包含立项。\n自主无厂商关系要求，完成后本人独占。联合须核心与已开放本厂关联部件；立项时展示可用部件，完成时仍须原证据及合法本厂样机。首次核心可按§5.3合并。\n到本模式工期且证据满足，领取印刷科技一次。缺证据停为待验证；以后一次研发选择它复核，不能同时研究别项。费用减免最低6，核心款另付。\n可在自己行动前免费放弃未完项目，牌进主弃、钱不退；不能中途改模式、补差买独占或撤回公开成果。','联合9现金/3进度，自主12/6，直接读卡而不是乘2。已有进度2，用强度3只补到3，不把剩下3格转给别的科研。')
set_('9.4','独立验证是研发的替代选项','任何强度研发都可改为独立验证，放弃该次常规进度：付12现金，公开基础≥12且至少2种特征的真实合法现货，得1科技。临时样机不能代替。\n每公司每当前供应世代最多一次，在本公司I—V格放已用片；不能补领过去世代，也不因取消、改号、授权、换核心或发布复位。\nT32降低产品门槛；U12/Q22降低现金；T39在验证后给一个已有项目1格额外进度，不立项、不叠实验室，也不产生预告。\n运营已统一承担补现金，删除独立“技术服务”行动入口。','科技22开放第五代后，可以做第五代验证；还没有进入第五代就不能预领。验证是整次研发行动，不能再使用该强度的4格常规进度。')
set_('9.5','一枚进度片只看当前模式终点','项目卡印两种费用与工期；在研时放联合模式片或按自主处理，用一枚进度片沿0—8条到所选工期。\n各卡进度不同，整体约两倍只是设计参考。项目终点不因本次行动强度、实验室或奖励而改变；强度改变一次投入多少。\n合法加速只作用于此次项目，超额不用。后续新项目需要另一次研发行动；发布奖励完成项目也不插入额外行动或预告。','T18联合工期5：强度3立项得4，之后强度1推进到5。自主工期8可两次强度3完成；时间取舍与现金取舍分开。')
set_('11.1','合作行动签一张合同','合作行动可从手牌签1张H，默认只有合同槽A，U10增加B；所有订单、供货、渠道、验证合同都占槽。关系与核心不占槽。\n先查前置，付费用或押金，放印刷期限片。签约后立即发生的发布也计一次。签约本身不建立伙伴；实际交付订单或验证结案才建立。\n本人行动前可免费终止，费用不退、押金没收；不能在锁定之后反悔。一次合作不同时建设施或换核心，附抽只入手。','H30仍独立单批订单；H21—H25需要完成相应厂联合研发，不要求另外开第二合同槽。')
set_('11.3','设施改善行动内部，不产生工作点','合作行动可改为建设1张手中U，付卡面现金与空间，通常共3格空间。本人行动前可拆除设施，移出不退钱。\nU02增加制造额度，U03增加调研取牌，U05—U08给研发项目加速，T36增加供应安装数；都不增加选择第二张行动牌的机会，也不改变所选原强度。\nU02每普通发布末仍付6维护，否则停用，以后本人行动开始前可付6启用。其他限次放在来源卡上。\n发布“建设支持”不执行合作行动、不触发合作附抽、不回溯本场收益。','强度1制造经U02最多2批，但原强度仍1，不能制造预告。强度3供应加T36最多3个不同栏，仍必须实际有牌、有钱且未锁定。')
set_('12.1','每批锁一个价、一个去向','每个产品选择18/28/38/48的一张价牌，再放唯一去向到四市场、合同A/B或留库。全员确认锁定后，揭晓配置、售价、去向和指派，再抽参考机。\n通常48价需基础≥28，并满足芯片≥12或影像≥8至少一项，明确卡牌许可除外；仍查市场资格与预算。使用权限和调校早在制造时确定，不能现在才付授权、补技术或更换适配对象。\n已公开但未售的产品保持公开配置，下场可以重新锁价与去向；锁定后不许变更。','科技获得新进度、供应开放新代，不会自动升级已经付钱的现货。扩产完全沿用本场锁好的原配置与价格。')
set_('13.8','最终成交才有一次参考挑战','扩产结束后，本公司真正零售成交的产品，其竞争力严格超过对应市场参考值，且该格有星，才可挑战。每家公司每场最多选一批一格，从收入、科技、特色三选一。\n卡上各格直接印奖：1/2/3星本版收入2/3/4，科技1/1/2，特色另读卡。不能击败弱项却拿该参考机强项的奖励。0星无额外奖。\n科技或工程试验另要求锁定时本产品部署至少一项本人完成研发；自己的公开署名可算，外部授权和集成位不能代替。\n新完成项目或新建立伙伴不回溯本场资格；扩产不重复领奖。','参考35分是2星：超过它并成交可选3收入、1科技或印刷特色。与参考同分时真人优先成交，但没有严格击败奖。')
set_('13.9','六种特色奖励当场结清','| 特色 | 1／2／3星具体额度 |\n| --- | --- |\n| 市场回款 | 8／16／24现金。 |\n| 商情报告 | 取1／2／3张主牌，选完一次补。 |\n| 工程试验 | 已有1个项目推进1／2／3格；另查本人科研资格。 |\n| 渠道回购 | 另一批合格未售零售货回购12／20／28现金，按消耗结束。 |\n| 供货签装 | 安装1张稳定，不执行供应行动，入库费减3／6／9至0。 |\n| 建设支持 | 建1设施，不执行合作行动，建设费减0／3／6至0。 |\n工程不立项、不叠普通研发加速、不溢出；完成也不预告、不临时给本场产品使用。奖励只入手不自动打牌，不形成跨期券。','被扩产挤掉的合法零售原批可回购；留库、超预算或错市场的不行。签装仍查手牌和引用锁定，建设仍查空间与现金。')
set_('14.1','完整发布：先锁定、再扩产、最后领奖','①锁价/去向，揭晓配置与指派，从本场参考代完整6张现抽1张。\n②核验原有现货的合同整单交付，暂不领款、退押、清卡。\n③冻结原产品竞争力与扩产费用；依大众→电竞→摄影→商务，临时分单、按序询问扩产、试排付款、确认本市场最终结果。\n④冻结全部成交、挑战、科研成果、授权和回购证据。\n⑤从触发者下一位起，领取合同、零售和普通成果，再结清现金、拿牌、工程、回购。\n⑥处理出口、Q21与证据；统一清理已售/处置产品及使用指派、＋1片，作者片永久不动。\n⑦结清签装/建设，处理期限、维护、每期复位及牌市/需求；开放本回合科技达到的新代、标定下场参考代、发布归0，最后检查双轨终局。','所有四市场扩产完成前，不领任何销售、合同、押金或挑战款。实际收到的别人扩产授权款可以用于之后的自己扩产。阵列在进发布前已整理，不因发布再重置。')
set_('15.1','标记相遇后，每人再行动一次','任意时点本人两标记相遇或越过，记录终局将触发；先完成当前回合所有效果及可能的普通发布。触发者是当前行动者，即使达标的是收授权或奖励的另一人。\n之后从当前行动者下一位起，每人再有一个完整回合，当前行动者最后；每回合仍只选一张六行动牌并正常整理阵列。\n最后阶段推满发布不再中途开普通发布；最后一人结束后，按已标定参考世代锁定、現抽并举行最终发布。没有第五代硬锁，也不因当前世代发布不足两次而延后。'.replace('現','现'),'本回合研发先让科技跨线，仍要完整处理它的效果、排程和应发生的发布；不是当场跳过其他玩家的最后行动。')
set_('15.2','最终计分：读取两标记之间的距离','最终发布照常合同交付、零售扩产、挑战、工程、回购、签装与建设；然后终止未完合同并没收押金。不抽下一场需求，不付下期维护，不改变阵列。\n以科技标记横向对齐的收入格为相遇线：收入已越过，超过几格得几分；还没到，差几格记负几分。两轨覆盖整个130格跨度。最高分获胜；同分比较剩余现金，仍同并列。\n超收入130后用数字筹码记录超出格数；超科技46后，每额外1科技继续跨近3收入格，单独放科技超出筹码。不把它绕回0重新用前8步比例。没有秘密终局目标。','科技22对齐收入72：收入80得8分，收入65得−7分。科技46对齐收入0；科技47相遇线越过收入0三格，收入2得5分。这只是读轨说明，不是固定倍数胜利公式。')
set_('15.3','首测参数与验证边界','本版从实际6.9迁移：六卡双行阵列、无通用工作点；制造/科研成果预告及有货宣发；科技领先4/9/15/22换代；收入130/科技46反向相遇；芯片12/14/17锚点并重标门槛、参考与需求。\n315种内容牌、50唯一芯片、初始件、四栏稳定库、单合同槽、公开授权与每公司每场一次扩产继续保留。\n每代约2场、第五代约2场为调参目标，不是固定流程或平衡结论。测试模型与实测分开，纸面节奏预算不冒充完整多人对局。具体覆盖与尚未达到的目标见验证记录。','连续运营但不造货不会推进发布；有货付费催开仍是正常竞争。极端研发可更快换代，极端不研发会更慢，规则不强制扳回两场。')
# fix cross references and old instructions in unchanged blocks only
replacements={'本人工作阶段':'本人行动阶段','正常工作阶段':'正常行动阶段','普通工作':'普通行动','制造工作':'制造行动','正常组装工作':'制造行动中的组装','制造总费':'制造总费','签装仍查手牌、实际入库费':'签装仍查手牌、实际入库费','不花工作':'不执行部门行动','不另花工作':'不额外执行行动'}
for sec in b['sections']:
 for bb in sec['blocks']:
  for key in ['body','aside']:
   for fr,to in replacements.items():bb[key]=bb[key].replace(fr,to)
# Final action-interface replacements in retained paragraphs.
for sec in b['sections']:
 for bb in sec['blocks']:
  for key in ['body','aside']:
   bb[key]=bb[key].replace('不执行部门行动点','不执行制造行动').replace('不额外花工作','不额外执行部门行动').replace('等本人工作、首次','等普通制造、首次').replace('两者均不是正常工作，不触发T36的一次安装两类或其他仅限正常工作的能力。','两者都不是供应或合作行动，不触发T36增加供应安装上限，也不触发这两项行动的附带抽牌。').replace('接下来的工作使用','接下来的行动使用')
# Existing T21 special occupancy remains unchanged.
(W/'v70_rulebook.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n')
lines=['# 旗舰元年7.0 完整规则书','双行排程与世代竞逐 · 2026年9月23日']
for sec in b['sections']:
 lines+=['\n## '+sec['number']+' '+sec['title'],sec['intro']]
 for bb in sec['blocks']:lines+=['\n### '+bb['title'],bb['body'],'\n> '+bb['asideKind']+'：'+bb['aside'].replace('\n','\n> ')]
(W/'v70_rules.md').write_text('\n\n'.join(lines)+'\n')
print('Rules',len(b['sections']),'chapters',sum(len(s['blocks']) for s in b['sections']),'blocks')
